WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue NULLS FIRST, id) AS dedup_rank FROM store_sales) ranked WHERE dedup_rank = 1) SELECT DATE_TRUNC('MONTH', sale_date) AS activity_month, product_id, PERCENTILE_APPROX(units, ARRAY(0.25, 0.5, 0.75)) AS units_quartiles, STDDEV_SAMP(revenue) AS revenue_stddev FROM deduped GROUP BY activity_month, product_id
